class TestTag:
    def test_valid_tag_normalizes(self):
        tag = Tag("  Hello_World  ")
        assert tag.name == "hello_world"

    @pytest.mark.parametrize("name", ["bug", "high-priority", "v2_feature", "abc123"])
    def test_valid_names(self, name):
