    @pytest.mark.parametrize(
        "name, error_type",
        [
            ("", ValueError),
            ("   ", ValueError),
            ("a" * 33, ValueError),
            ("bad char!", ValueError),
            ("has space", ValueError),
            (123, TypeError),
            (None, TypeError),
        ],
        ids=["empty", "whitespace", "too-long", "illegal-char", "space", "int", "none"],
    )
    def test_invalid_names(self, name, error_type):
        with pytest.raises(error_type):
